// table_terms.hpp - Interpretation of the coefficient tables of c++/symmetry/coefnew
//
// The Hamiltonian tables (*-offdiag.dat, *-diag.dat, *-isospinx.dat, ...) and the tables of global operators
// (*-qtot.dat, *-spinz.dat, ...) generated by nrgcoef.m are sequences of statements such as
//
//   OFFDIAG(i, j, ch, factor);    DIAG(i, ch, number);    QTOT(i1, ip, ch, value);
//
// whose factors are expressions in the quantum numbers of the subspace (local variables such as ss, q1). Each
// statement is a macro defined once below; it calls the method of the same name of a context object T, which must be
// in scope where a table is included: a ShellTerms object in make_matrix() and a GlobalTerms object in
// recalc_global(). The context selects the Wilson-chain coefficients and the channel. For OFFDIAG-like statements the
// macro first checks that the matrix block (i,j) exists, so that the factor is not evaluated otherwise (it may divide
// by zero for such blocks).

#ifndef _table_terms_hpp_
#define _table_terms_hpp_

#include <cstddef>
#include <optional>

#include "coef.hpp"
#include "invar.hpp"
#include "operators.hpp"
#include "step.hpp"
#include "subspaces.hpp"
#include "symmetry.hpp"
#include "traits.hpp"

namespace NRG {

// Terms of the Hamiltonian of an invariant subspace that involve the added site(s), make_matrix(). With substeps, the
// shell is a single site of channel M (step.NM()), and the channel argument of the tables (always 0) is replaced by M.
template<scalar S>
class ShellTerms {
 protected:
   using Matrix = Matrix_traits<S>;
   using t_coef = coef_traits<S>;
   const Symmetry<S> &sym;
   const Step &step;
   Matrix &h;
   const SubspaceDimensions &qq;
   const InvarVec &In;
   const Opch<S> &opch;
   const Coef<S> &coef;
   std::size_t N;                // index of the previous site; the added site is N+1
   std::optional<std::size_t> M; // channel of the added site with substeps
   bool polarized;               // spin-dependent coefficients
   bool conj_delta;              // the pairing term uses conj(delta), see Symmetry::uses_pairing()
   [[nodiscard]] std::size_t chan(const std::size_t ch) const { return M ? *M : ch; }
   // Hopping between the added site and the previous site, through the block (ch, fnr) of <||f||>
   void hop(const std::size_t i, const std::size_t j, const std::size_t ch, const std::size_t fnr, const t_coef factor) const {
     sym.offdiag_function_impl(step, i, j, ch, fnr, factor, h, qq, In, opch);
   }
 public:
   ShellTerms(const Symmetry<S> &sym, const Params &P, const Step &step, Matrix &h, const SubspaceDimensions &qq, const InvarVec &In,
              const Opch<S> &opch, const Coef<S> &coef, const bool conj_delta = true)
     : sym(sym), step(step), h(h), qq(qq), In(In), opch(opch), coef(coef), N(P.substeps ? step.NM().first : step.N()),
       polarized(P.polarized), conj_delta(conj_delta) {
     if (P.substeps) M = step.NM().second;
   }
   [[nodiscard]] bool contributes(const std::size_t i, const std::size_t j) const { return qq.offdiag_contributes(i, j); }
   // For OFFDIAG; derived contexts can exclude further blocks (whose factor must not be evaluated)
   [[nodiscard]] bool contributes_offdiag(const std::size_t i, const std::size_t j) const { return contributes(i, j); }

   // OFFDIAG: hopping xi between the added site and the previous one (block 0 of <||f||>); without ch: channel 0
   void offdiag(const std::size_t i, const std::size_t j, const std::size_t ch, const t_coef factor) const {
     hop(i, j, chan(ch), 0, factor * coef.xi(N, chan(ch)));
   }
   void offdiag(const std::size_t i, const std::size_t j, const t_coef factor) const { offdiag(i, j, 0, factor); }
   // OFFDIAG_1, OFFDIAG_2: block fnr of <||f||> (SU2, DBLSU2)
   void offdiag_block(const std::size_t fnr, const std::size_t i, const std::size_t j, const std::size_t ch, const t_coef factor) const {
     hop(i, j, chan(ch), fnr, factor * coef.xi(N, chan(ch)));
   }
   // OFFDIAG_CR_UP, ...: block fnr of <||f||> for spin up or down, with spin-dependent hopping in polarized chains (PP)
   void offdiag_spin(const std::size_t fnr, const bool up, const std::size_t i, const std::size_t j, const std::size_t ch,
                     const t_coef factor) const {
     const auto c = chan(ch);
     const t_coef xi = !polarized ? coef.xi(N, c) : (up ? coef.xiUP(N, c) : coef.xiDOWN(N, c));
     hop(i, j, c, fnr, factor * xi);
   }
   // OFFDIAG_MIX, RUNGHOP: channel-mixing terms (QS with rungs)
   void offdiag_mix(const std::size_t i, const std::size_t j, const std::size_t ch, const t_coef factor) const {
     hop(i, j, chan(ch), 0, factor * coef.xiR(N, chan(ch)));
   }
   void runghop(const std::size_t i, const std::size_t j, const t_coef factor) const {
     sym.diag_offdiag_function(step, i, j, factor * coef.zetaR(N + 1, 0), h, qq);
   }
   // ANOMALOUS: anomalous hopping kappa
   void anomalous(const std::size_t i, const std::size_t j, const std::size_t ch, const t_coef factor) const {
     hop(i, j, chan(ch), 0, factor * coef.kappa(N, chan(ch)));
   }
   void anomalous(const std::size_t i, const std::size_t j, const t_coef factor) const { anomalous(i, j, 0, factor); }
   // DIAG: on-site energy zeta; 'number' is the number of electrons of the added site in the combination i
   void diag(const std::size_t i, const std::size_t ch, const double number) const {
     sym.diag_function(step, i, number, coef.zeta(N + 1, chan(ch)), h, qq);
   }
   void diag(const std::size_t i, const double number) const { diag(i, 0, number); }
   // DIAG_UP, DIAG_DOWN: spin-resolved on-site energy in polarized chains (PP); j is not used
   void diag_spin(const bool up, const std::size_t i, [[maybe_unused]] const std::size_t j, const std::size_t ch, const double number) const {
     const auto c = chan(ch);
     sym.diag_function_half(step, i, number, up ? coef.zetaUP(N + 1, c) : coef.zetaDOWN(N + 1, c), h, qq);
   }
   // ISOSPINX: on-site pairing delta; the factor 2 is due to the definition of the isospin as 1/2 of the pairing operator
   void isospinx(const std::size_t i, const std::size_t j, const std::size_t ch, const t_coef factor) const {
     const t_coef delta = coef.delta(N + 1, chan(ch));
     sym.diag_offdiag_function(step, i, j, factor * 2.0 * (conj_delta ? conj_me(delta) : delta), h, qq);
   }
   void isospinx(const std::size_t i, const std::size_t j, const t_coef factor) const { isospinx(i, j, 0, factor); }
};

// Matrix elements <I||O||I> of a global operator O of the added site(s) (recalc_global()): the statements of the table
// add value * <I|i1><ip|I> to the matrix element cn of the subspace I. The transverse isospin components are multiplied
// by 'iso', the sign of the isospin of the added site on a bipartite chain.
template<scalar S>
class GlobalTerms {
   using t_coef = coef_traits<S>;
   const Symmetry<S> &sym;
   const DiagInfo<S> &diag;
   const Invar &I;
   Matrix_traits<S> &cn;
   double iso;
 public:
   GlobalTerms(const Symmetry<S> &sym, const DiagInfo<S> &diag, const Invar &I, Matrix_traits<S> &cn, const double iso = 1.0)
     : sym(sym), diag(diag), I(I), cn(cn), iso(iso) {}
   void add(const std::size_t i1, const std::size_t ip, [[maybe_unused]] const std::size_t ch, const t_coef value) const {
     sym.recalc1_global(diag, I, cn, i1, ip, value);
   }
   void add_iso(const std::size_t i1, const std::size_t ip, [[maybe_unused]] const std::size_t ch, const t_coef value) const {
     sym.recalc1_global(diag, I, cn, i1, ip, value * iso);
   }
   void isospinx(const std::size_t i1, const std::size_t ip, const std::size_t ch, const t_coef value) const { add_iso(i1, ip, ch, value); }
};

} // namespace NRG

// Statements of the Hamiltonian tables
#define OFFDIAG(i, j, ...) if (terms.contributes_offdiag(i, j)) terms.offdiag(i, j, __VA_ARGS__)
#define OFFDIAG_1(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_block(0, i, j, __VA_ARGS__)
#define OFFDIAG_2(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_block(1, i, j, __VA_ARGS__)
#define OFFDIAG_CR_DO(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_spin(0, false, i, j, __VA_ARGS__)
#define OFFDIAG_CR_UP(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_spin(1, true, i, j, __VA_ARGS__)
#define OFFDIAG_AN_DO(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_spin(2, false, i, j, __VA_ARGS__)
#define OFFDIAG_AN_UP(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_spin(3, true, i, j, __VA_ARGS__)
#define OFFDIAG_MIX(i, j, ...) if (terms.contributes(i, j)) terms.offdiag_mix(i, j, __VA_ARGS__)
#define ANOMALOUS(i, j, ...) if (terms.contributes(i, j)) terms.anomalous(i, j, __VA_ARGS__)
#define RUNGHOP(...) terms.runghop(__VA_ARGS__)
#define DIAG(...) terms.diag(__VA_ARGS__)
#define DIAG_UP(...) terms.diag_spin(true, __VA_ARGS__)
#define DIAG_DOWN(...) terms.diag_spin(false, __VA_ARGS__)
#define ISOSPINX(...) terms.isospinx(__VA_ARGS__)

// Statements of the tables of global operators (and ISOSPINX above, which calls GlobalTerms::isospinx())
#define QTOT(...) terms.add(__VA_ARGS__)
#define QDIFF(...) terms.add(__VA_ARGS__)
#define Q1(...) terms.add(__VA_ARGS__)
#define Q2(...) terms.add(__VA_ARGS__)
#define N1(...) terms.add(__VA_ARGS__)
#define N2(...) terms.add(__VA_ARGS__)
#define N3(...) terms.add(__VA_ARGS__)
#define CHARGE(...) terms.add(__VA_ARGS__)
#define SPINX(...) terms.add(__VA_ARGS__)
#define SPINY(...) terms.add(__VA_ARGS__)
#define SPINZ(...) terms.add(__VA_ARGS__)
#define ISOSPINZ(...) terms.add(__VA_ARGS__)
#define ISOSPINP(...) terms.add_iso(__VA_ARGS__)
#define ISOSPINM(...) terms.add_iso(__VA_ARGS__)
#define ISOSPINY(...) terms.add_iso(__VA_ARGS__)

#endif
